BEGIN;

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', v.viz)
FROM (VALUES

  ('ap-server-q45', '<svg viewBox="0 0 340 130" xmlns="http://www.w3.org/2000/svg"><text x="170" y="16" text-anchor="middle" font-size="11" fill="#8892a4">3つの工程の処理能力(件/時)</text><rect x="20" y="32" width="100" height="18" fill="#3b82f6"/><text x="130" y="45" font-size="10" fill="#8892a4">工程A 100件</text><rect x="20" y="58" width="60" height="18" fill="#c47070"/><text x="90" y="71" font-size="10" fill="#c47070">工程B 60件 ← 一番遅い</text><rect x="20" y="84" width="90" height="18" fill="#3b82f6"/><text x="120" y="97" font-size="10" fill="#8892a4">工程C 90件</text><text x="170" y="118" text-anchor="middle" font-size="11" fill="#c9a04a">全体の処理能力 = 60件/時（工程Bが上限）</text></svg>'),

  ('ap-server-q51', '<svg viewBox="0 0 340 150" xmlns="http://www.w3.org/2000/svg"><text x="170" y="16" text-anchor="middle" font-size="11" fill="#8892a4">増分バックアップの復元に必要な鎖</text><rect x="20" y="35" width="70" height="24" fill="#3b82f6"/><text x="55" y="51" text-anchor="middle" font-size="10" fill="#e8eaf0">月 フル</text><rect x="105" y="35" width="70" height="24" fill="#6ab08d"/><text x="140" y="51" text-anchor="middle" font-size="10" fill="#e8eaf0">火 増分</text><rect x="190" y="35" width="70" height="24" fill="#6ab08d"/><text x="225" y="51" text-anchor="middle" font-size="10" fill="#e8eaf0">水 増分</text><line x1="90" y1="47" x2="105" y2="47" stroke="#8892a4" stroke-width="2"/><line x1="175" y1="47" x2="190" y2="47" stroke="#8892a4" stroke-width="2"/><text x="170" y="80" text-anchor="middle" font-size="10" fill="#8892a4">水曜の復元には3つすべてを順番に適用する</text><text x="170" y="98" text-anchor="middle" font-size="11" fill="#c9a04a">1つでも欠けると鎖がつながらない</text></svg>'),

  ('ap-server-q58', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><text x="170" y="16" text-anchor="middle" font-size="11" fill="#8892a4">NASとSANの違い</text><rect x="30" y="35" width="120" height="70" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="90" y="55" text-anchor="middle" font-size="11" fill="#60a5fa">NAS</text><text x="90" y="75" text-anchor="middle" font-size="10" fill="#8892a4">ファイル単位</text><text x="90" y="92" text-anchor="middle" font-size="9" fill="#8892a4">「このファイルちょうだい」</text><rect x="190" y="35" width="120" height="70" rx="4" fill="none" stroke="#c9a04a" stroke-width="1.5"/><text x="250" y="55" text-anchor="middle" font-size="11" fill="#c9a04a">SAN</text><text x="250" y="75" text-anchor="middle" font-size="10" fill="#8892a4">ブロック単位</text><text x="250" y="92" text-anchor="middle" font-size="9" fill="#8892a4">ディスクの一部を直接読み書き</text><text x="170" y="128" text-anchor="middle" font-size="10" fill="#8892a4">どちらもネットワーク越しに複数サーバーで共有できる点は共通</text></svg>'),

  ('ap-server-q64', '<svg viewBox="0 0 340 160" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" text-anchor="middle" font-size="11" fill="#8892a4">利用者が管理する範囲（青）</text><text x="60" y="28" text-anchor="middle" font-size="10" fill="#e8eaf0">IaaS</text><text x="170" y="28" text-anchor="middle" font-size="10" fill="#e8eaf0">PaaS</text><text x="280" y="28" text-anchor="middle" font-size="10" fill="#e8eaf0">SaaS</text><rect x="30" y="35" width="60" height="18" fill="#3b82f6"/><rect x="30" y="55" width="60" height="18" fill="#3b82f6"/><rect x="30" y="75" width="60" height="18" fill="#6ab08d"/><rect x="30" y="95" width="60" height="18" fill="#6ab08d"/><rect x="140" y="35" width="60" height="18" fill="#3b82f6"/><rect x="140" y="55" width="60" height="18" fill="#6ab08d"/><rect x="140" y="75" width="60" height="18" fill="#6ab08d"/><rect x="140" y="95" width="60" height="18" fill="#6ab08d"/><rect x="250" y="35" width="60" height="18" fill="#6ab08d"/><rect x="250" y="55" width="60" height="18" fill="#6ab08d"/><rect x="250" y="75" width="60" height="18" fill="#6ab08d"/><rect x="250" y="95" width="60" height="18" fill="#6ab08d"/><text x="20" y="47" text-anchor="end" font-size="8" fill="#8892a4">アプリ</text><text x="20" y="67" text-anchor="end" font-size="8" fill="#8892a4">OS/MW</text><text x="20" y="87" text-anchor="end" font-size="8" fill="#8892a4">仮想化</text><text x="20" y="107" text-anchor="end" font-size="8" fill="#8892a4">HW</text><text x="170" y="130" text-anchor="middle" font-size="10" fill="#3b82f6">青=自分で管理</text><text x="170" y="146" text-anchor="middle" font-size="10" fill="#6ab08d">緑=事業者が管理</text></svg>')

) AS v(source_ref, viz)
WHERE q.source_ref = v.source_ref
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'ap-server')
  AND q.explanation_data IS NOT NULL;

COMMIT;
